'use strict';
// City filters are point attributes. They do not change the climate raster.
class CityMapOverlay{
 constructor(navigation,discovery,filters,getState,inspect){this.navigation=navigation;this.discovery=discovery;this.filters=filters;this.getState=getState;this.inspect=inspect;this.features=[];this.entries=new Map();this.popup=new maplibregl.Popup({closeButton:false,closeOnClick:false,offset:12});navigation.ready.then(()=>{this.install();this.refresh();});}
 install(){const map=this.navigation.map;if(map.getSource('city-filter-points'))return;map.addSource('city-filter-points',{type:'geojson',data:{type:'FeatureCollection',features:[]}});const visibility=['step',['zoom'],['case',['>=',['get','population'],500000],.9,0],3,['case',['>=',['get','population'],100000],.9,0],5,.9];map.addLayer({id:'city-filter-points',type:'circle',source:'city-filter-points',paint:{'circle-radius':['interpolate',['linear'],['zoom'],0,3,4,4,8,7],'circle-color':['case',['get','unknown'],'rgba(0,0,0,0)',['get','color']],'circle-stroke-color':['case',['get','unknown'],'#0a2463','#ffffff'],'circle-stroke-width':['case',['get','unknown'],2,1.5],'circle-opacity':visibility,'circle-stroke-opacity':visibility}});map.on('mousemove','city-filter-points',e=>{const feature=e.features?.[0],entry=feature&&this.entries.get(Number(feature.properties.id));if(!entry)return;const box=document.createElement('div');box.className='city-filter-popup';const heading=document.createElement('strong');heading.textContent=entry.name;box.append(heading);const line=t=>{const p=document.createElement('p');p.textContent=t;box.append(p);};line(entry.subtitle);line(`${Number(entry.score).toFixed(1)} / 10 · ${Number(entry.days).toFixed(1)} comfortable days/year`);const assessment=this.filters.assessment(entry),reasons=[...assessment.failures,...assessment.missing];line(assessment.status==='fail'?'Outside filters':assessment.status==='unknown'?'Unknown data · kept in results':'Matches city filters');if(reasons.length){const ul=document.createElement('ul');for(const text of reasons){const li=document.createElement('li');li.textContent=text;ul.append(li);}box.append(ul);}const n=this.filters.nomads.get(entry.place[0]),h=this.filters.crimeRecord(entry.place);if(n)line(`Nomads ${n.score.toFixed(1)}/5 · ${n.monthly_cost_usd>0?'$'+Math.round(n.monthly_cost_usd).toLocaleString('en')+'/month':'cost unknown'}`);if(h)line(`${this.filters.crimeScope} homicide: ${h.value.toFixed(1)}/100,000 · ${h.year}`);if(h?.area)line(`${h.source} · ${h.area} · ${h.geography}`);line('Click to inspect this city');const coords=feature.geometry.coordinates.slice();while(Math.abs(e.lngLat.lng-coords[0])>180)coords[0]+=e.lngLat.lng>coords[0]?360:-360;this.popup.setLngLat(coords).setDOMContent(box).addTo(map);});map.on('mouseleave','city-filter-points',()=>this.popup.remove());map.on('movestart',()=>this.popup.remove());map.on('moveend',()=>this.refresh());}
 color(value){const m=this.navigation.meta,q=Math.max(0,Math.min(1,value/(this.getState().view==='days'?150:10)))*12,a=Math.min(11,Math.floor(q)),rgb=this.navigation.rgb;return '#'+rgb[a].map((c,i)=>Math.round(c+(rgb[a+1][i]-c)*(q-a)).toString(16).padStart(2,'0')).join('');}
 export(ctx,x,y,w,h,bounds){if(!this.features.length)return;const west=bounds[0][1],east=bounds[1][1],south=bounds[0][0],north=bounds[1][0];ctx.save();for(const f of this.features){const [lon,lat]=f.geometry.coordinates;if(lon<west||lon>east||lat<south||lat>north)continue;ctx.beginPath();ctx.arc(x+(lon-west)/(east-west)*w,y+(north-lat)/(north-south)*h,4.5,0,Math.PI*2);ctx.fillStyle=f.properties.color;ctx.fill();ctx.strokeStyle=f.properties.unknown?'#53637c':'#ffffff';ctx.lineWidth=1.5;ctx.stroke();}ctx.restore();}
 refresh(){const s=this.getState(),map=this.navigation.map;if(!this.navigation.loaded||!map.getSource('city-filter-points')||!s.scoreValues||s.busy)return;const mode=document.getElementById('city-map-effect').value,enabled=mode!=='ranking',active=this.filters.active,minimum=Number(document.getElementById('rank-population').value),filterState=this.filters.state,climate=window.ComfyDays?.match,bounds=map.getBounds(),zoom=map.getZoom(),visiblePopulation=zoom<3?500000:zoom<5?100000:1000,center=map.getCenter().lng,padX=(bounds.getEast()-bounds.getWest())*.25,padY=(bounds.getNorth()-bounds.getSouth())*.25,signature=JSON.stringify([mode,this.filters.signature,s.currentRegion,s.view,minimum,climate,visiblePopulation,bounds.toArray()]);if(this.lastSignature===signature&&this.lastScores===s.scoreValues&&this.lastDays===s.dayValues)return;this.lastSignature=signature;this.lastScores=s.scoreValues;this.lastDays=s.dayValues;this.popup.remove();this.entries.clear();let matched=0,excluded=0,unknown=0;const features=[];if(enabled)for(const e of this.discovery.candidates(true)){const populationFailed=e.population<minimum||climate?.enabled&&(s.scoreValues[e.index]<climate.score||s.dayValues[e.index]<climate.days),a=populationFailed?null:this.filters.assessment(e,filterState),missing=a?.status==='unknown',outside=populationFailed||a?.status==='fail';if(outside)excluded++;else if(missing)unknown++;else matched++;if(outside||missing||climate?.enabled&&(s.scoreValues[e.index]<climate.score||s.dayValues[e.index]<climate.days)||e.population<visiblePopulation)continue;const lon=e.place[3]+360*Math.round((center-e.place[3])/360);if(e.population<visiblePopulation||e.place[2]<bounds.getSouth()-padY||e.place[2]>bounds.getNorth()+padY||lon<bounds.getWest()-padX||lon>bounds.getEast()+padX)continue;const entry={...e,score:s.scoreValues[e.index],days:s.dayValues[e.index]};this.entries.set(e.place[0],entry);features.push({type:'Feature',geometry:{type:'Point',coordinates:[e.place[3],e.place[2]]},properties:{id:e.place[0],population:e.population,unknown:missing,excluded:outside,color:outside?'#69758a':this.color(s.view==='days'?entry.days:entry.score)}});}this.features=features;this.counts={matched,excluded,unknown};map.getSource('city-filter-points').setData({type:'FeatureCollection',features});document.getElementById('city-marker-legend').hidden=!features.length;const status=document.getElementById('city-map-status');if(status)status.textContent=this.filters.active&&!this.filters.ready&&!this.filters.error?'Loading city data…':!enabled?'City filters apply to the ranking only.':!features.length?((matched+unknown)===0?'No map cities match. Adjust Cities filters.':'No points at this zoom or location. Zoom in or move the map.'):`${matched.toLocaleString('en')} match · ${excluded.toLocaleString('en')} ${mode==='results'?'hidden':'outside'} · ${unknown.toLocaleString('en')} unknown, kept.`;}

}
window.CityMapOverlay=CityMapOverlay;
